validator:
function validate(input) {
  const [{ Queue = [] }] = input;
  const n = Queue.length;
  if (n === 0) return 'Queue needs at least one person.';
  const ids = new Set(), turns = new Set();
  for (const row of Queue) {
    if (row.some((v) => v === null)) return 'Queue rows may not contain null.';
    const [id, , weight, turn] = row;
    if (!(id >= 1 && id <= n) || ids.has(id)) return `person_id must be each of 1..${n} once; ${id} is not.`;
    if (!(turn >= 1 && turn <= n) || turns.has(turn)) return `turn must be each of 1..${n} once; ${turn} is not.`;
    ids.add(id);
    turns.add(turn);
    if (weight <= 0) return `Weights must be positive; person ${id} weighs ${weight}.`;
    if (turn === 1 && weight > 1000) return 'The first person must weigh at most 1000.';
  }
  return null;
}

generator:
function generate(rand, size) {
  const shuffle = (list) => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  const small = size === 'small';
  const n = small ? 1 + Math.floor(rand() * 8) : 2000;
  const ids = shuffle(Array.from({ length: n }, (_, i) => i + 1));
  const turns = shuffle(Array.from({ length: n }, (_, i) => i + 1));
  const names = shuffle(['Alice', 'Bob', 'Alex', 'John Cena', 'Winston', 'Marie', 'Priya', 'Tom']);
  // Round weights make the total land exactly on 1000 often; an occasional giant blocks everyone behind.
  const weights = [100, 150, 200, 250, 300, 350, 400, 500, 1000];
  const Queue = [];
  for (let i = 0; i < n; i++) {
    let weight = small ? weights[Math.floor(rand() * weights.length)] : 1 + Math.floor(rand() * 15);
    if (turns[i] !== 1 && rand() < 0.08) weight = 1200;
    Queue.push([ids[i], small ? names[i] : `P${ids[i]}`, weight, turns[i]]);
  }
  return [{ Queue }];
}
